from pathlib import Path
p=Path("runtime/src/builtin_number.c")
s=p.read_text()
def rb(start,end,repl):
    global s
    a=s.index(start); b=s.index(end,a); s=s[:a]+repl+s[b:]
rb('static f64 mal_builtin_parse_float_units(', '/**\n * Number(value):', 'static f64 mal_builtin_parse_float_units(const c16 *code_units, usize length) {\n    usize start = 0;\n    while (start < length && mal_ecma_is_string_whitespace(code_units[start])) {\n        start++;\n    }\n\n    // Most protocol and application numbers fit in the native frame. Retain a\n    // transient heap buffer only for unusually long prefixes accepted by strtod.\n    usize available = length - start;\n    byte stack_buffer[64];\n    byte *buffer = available < sizeof(stack_buffer)\n        ? stack_buffer\n        : malloc(available + 1);\n    bool heap_buffer = buffer != stack_buffer;\n    usize buffer_length = 0;\n    for (usize i = start; i < length; i++) {\n        if (code_units[i] > 0x7F) {\n            break;\n        }\n        buffer[buffer_length++] = (byte) code_units[i];\n    }\n    buffer[buffer_length] = \'\\0\';\n\n    // JS parseFloat has no hex or "inf" forms; strtod would accept both.\n    usize digits_start =\n        buffer_length > 0 && (buffer[0] == \'+\' || buffer[0] == \'-\') ? 1 : 0;\n    if (buffer_length >= digits_start + 2 && buffer[digits_start] == \'0\' &&\n        (buffer[digits_start + 1] == \'x\' || buffer[digits_start + 1] == \'X\')) {\n        buffer[digits_start + 1] = \'\\0\';\n    }\n    // parseFloat accepts a leading "Infinity" (exact spelling, after an optional\n    // sign); strtod would otherwise also accept "inf"/"infinity"/"nan", which\n    // the StrDecimalLiteral grammar does not.\n    if (buffer_length >= digits_start + 8 &&\n        memcmp(buffer + digits_start, "Infinity", 8) == 0) {\n        bool negative = digits_start == 1 && buffer[0] == \'-\';\n        if (heap_buffer) free(buffer);\n        return negative ? -INFINITY : INFINITY;\n    }\n    if (buffer_length > digits_start &&\n        (buffer[digits_start] == \'i\' || buffer[digits_start] == \'I\' ||\n         buffer[digits_start] == \'n\' || buffer[digits_start] == \'N\')) {\n        buffer[digits_start] = \'\\0\';\n    }\n\n    byte *end = buffer;\n    f64 value = strtod(buffer, (char **) &end);\n    bool parsed = end != buffer;\n    if (heap_buffer) free(buffer);\n    return parsed ? value : NAN;\n}\n\n')
rb('static MalValue mal_builtin_parse_int(', 'static MalValue mal_builtin_global_is_nan(', 'static MalValue mal_builtin_parse_int(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) this_value;\n    (void) new_target;\n    (void) callee;\n    MalValue input = arg_count >= 1 ? args[0] : mal_value_new_undefined();\n    bool zero_number =\n        mal_ops_is_number(input) && mal_ops_number_as_f64(input) == 0.0;\n    bool simple_number = mal_value_is_int32(input) || zero_number;\n\n    // ToString(input) has no observable work for these primitive Numbers, so\n    // radix coercion may run first and a decimal parse can return without\n    // allocating the intermediate String. Object input still preserves the\n    // mandated ToString-before-radix coercion order below.\n    if (simple_number) {\n        f64 radix = 0;\n        if (arg_count >= 2 && !mal_vm_to_number(vm, args[1], &radix)) {\n            return mal_value_new_undefined();\n        }\n        i32 int_radix = mal_ops_number_to_i32(radix);\n        if (int_radix == 0 || int_radix == 10) {\n            return zero_number ? mal_value_from_i32(0) : input;\n        }\n        MalString *string = mal_ops_to_string(&vm->heap, input);\n        return mal_ops_number_value(mal_builtin_parse_int_units(\n            mal_string_code_units(string), mal_string_length(string), radix));\n    }\n\n    MalString *string;\n    if (!mal_vm_to_string(vm, input, &string)) {\n        return mal_value_new_undefined();\n    }\n    f64 radix = 0;\n    if (arg_count >= 2 && !mal_vm_to_number(vm, args[1], &radix)) {\n        return mal_value_new_undefined();\n    }\n    return mal_ops_number_value(mal_builtin_parse_int_units(\n        mal_string_code_units(string), mal_string_length(string), radix));\n}\n\nstatic MalValue mal_builtin_parse_float(\n    MalVm *vm,\n    MalValue this_value,\n    const MalValue *args,\n    i32 arg_count,\n    MalValue new_target,\n    MalValue callee\n) {\n    (void) this_value;\n    (void) new_target;\n    (void) callee;\n    if (arg_count < 1) {\n        return mal_value_new_nan();\n    }\n    MalValue input = args[0];\n    if (mal_ops_is_number(input)) {\n        // Number::toString round-trips every nonzero Number. Zero is special:\n        // ToString(-0) is "0", so parseFloat must return positive zero.\n        return mal_ops_number_as_f64(input) == 0.0 ? mal_value_from_i32(0) : input;\n    }\n    MalString *string;\n    if (!mal_vm_to_string(vm, input, &string)) {\n        return mal_value_new_undefined();\n    }\n    return mal_ops_number_value(mal_builtin_parse_float_units(\n        mal_string_code_units(string), mal_string_length(string)));\n}\n\n')
